CREATE TABLE participants (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), email text, phone text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), starts_at timestamptz NOT NULL, cutoff_at timestamptz NOT NULL, capacity integer NOT NULL CHECK(capacity>0), host_ready boolean NOT NULL DEFAULT false, CHECK(cutoff_at<=starts_at));
CREATE TABLE registrations (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), participant_id uuid NOT NULL REFERENCES participants(id), session_id uuid REFERENCES sessions(id), registration_state text NOT NULL DEFAULT 'DRAFT' CHECK(registration_state IN ('DRAFT','ELIGIBLE','CONFIRMED','CANCELLED')), attendance_state text NOT NULL DEFAULT 'NOT_CHECKED_IN' CHECK(attendance_state IN ('NOT_CHECKED_IN','CHECKED_IN','ATTENDANCE_VERIFIED','COMPLETED','NO_SHOW')), result_state text NOT NULL DEFAULT 'NOT_RECEIVED' CHECK(result_state IN ('NOT_RECEIVED','VALIDATED','HOLD','APPROVED','RELEASED')), shipment_state text CHECK(shipment_state IN ('label_created','handed_to_courier')), external_registration_state text NOT NULL DEFAULT 'NOT_REGISTERED' CHECK(external_registration_state IN ('NOT_REGISTERED','REGISTERED','REVIEW')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX registrations_participant ON registrations(participant_id);
CREATE TABLE payments (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), minor_units bigint NOT NULL CHECK(minor_units>=0), currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'), payment_state text NOT NULL DEFAULT 'PENDING' CHECK(payment_state IN ('PENDING','VERIFIED','REVIEW','REFUNDED')));
CREATE TABLE payment_allocations (payment_id uuid PRIMARY KEY REFERENCES payments(id), registration_id uuid NOT NULL REFERENCES registrations(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inbound_receipts (id uuid PRIMARY KEY, provider text NOT NULL CHECK(provider<>''), event_key text NOT NULL CHECK(event_key<>''), fingerprint text NOT NULL CHECK(fingerprint ~ '^[0-9a-f]{64}$'), received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,event_key));
CREATE TABLE audit_events (id uuid PRIMARY KEY, object_id uuid NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox (id uuid PRIMARY KEY, object_id uuid NOT NULL, event_kind text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE artifacts (id uuid PRIMARY KEY, sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'), private_reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE policy_versions (id uuid PRIMARY KEY, kind text NOT NULL, version bigint NOT NULL CHECK(version>0), values jsonb NOT NULL, active boolean NOT NULL DEFAULT false CHECK(NOT active), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kind,version));
CREATE FUNCTION reject_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable record'; END $$;
CREATE TRIGGER artifacts_immutable BEFORE UPDATE OR DELETE ON artifacts FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER receipts_immutable BEFORE UPDATE OR DELETE ON inbound_receipts FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER policies_immutable BEFORE UPDATE OR DELETE ON policy_versions FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
